  for(const r of sample.requests) {const name=path.basename(r.url);if(!fs.existsSync(path.join(fixture,name))) fs.symlinkSync(path.join(cache,name),path.join(fixture,name));}
  const name='ldem_75n_240m_float.img',file=path.join(fixture,name);fs.unlinkSync(file);
  execFileSync('cp',['-c',path.join(cache,name),file]);
  const size=180/2**h.level,lat=-90+(h.y+.5)*size,lon=-180+(h.x+1)*size;
  const rho=2*R*Math.tan((90-lat)*rad/2)/240,cx=3812/2-.5;
