  const fillName='ldem_128_float.img',fillFile=path.join(fixture,fillName);fs.unlinkSync(fillFile);execFileSync('cp',['-c',path.join(cache,fillName),fillFile]);
  const ff=fs.openSync(fillFile,'r+'),row=Math.floor((90-lat)*128-.5),col=Math.floor(((lon+360)%360)*128-.5);
  const nanRow=Buffer.alloc(40*4);for(let i=0;i<40;i++)nanRow.writeFloatLE(NaN,i*4);
  for(let y=row-20;y<row+20;y++)fs.writeSync(ff,nanRow,0,nanRow.length,(y*46080+col-20)*4);fs.closeSync(ff);
  const refused=await encode(l,sample,[keyOf(h)],fixture);assert.equal(refused.response.statusCode,422);assert.equal(refused.response.errorCode,'fill-nodata');
  t.diagnostic(`synthetic hole: ${holes} filled and ${feather} feather vertices checked against independent bilinear/Euclidean reference; fill-nodata 422`);
  // The full, untrimmed production N60 unit exercises the decode-memory split,
  // every emitted request, the 321-post lattice and all its complete block files.
  const production={...MOON_CONFIG,caps:[cap('ldem_4',0,2),LADDER[11]],fill_diagnostics:1};
  const full=await lane(production),fullUnit=await full.planUnit(1);
  await prepare(fullUnit);
  const fullResult=success(await full.encode(fullUnit));
  assert.equal(fullResult.byKey.size,fullUnit.headers.length);
  const parity=await lane(production,{wasmPath:path.join(root,'data-source/terrain-source/dist/parity/module.wasm')});
